{
  "findings": [
    {
      "check_id": "CKV_AWS_40",
      "title": "Ensure IAM policies are attached only to groups or roles",
      "resource": "aws_iam_user_policy_attachment.privesc19-UpdateExistingGlueDevEndpoint-user-attach-policy",
      "severity": "MEDIUM",
      "explanation": "Attaching IAM policies directly to users can lead to excessive privileges and increased management complexity."
    }
  ],
  "patched_code": "resource \"aws_iam_role_policy_attachment\" \"privesc19-UpdateExistingGlueDevEndpoint-role-attach-policy\" {\n  role       = aws_iam_role.privesc19-UpdateExistingGlueDevEndpoint-role.name\n  policy_arn = aws_iam_policy.privesc19-UpdateExistingGlueDevEndpoint.arn\n}",
  "fix_summary": "Replaced aws_iam_user_policy_attachment with aws_iam_role_policy_attachment to attach the policy to a role instead of a user, reducing access management complexity."
}
